package com.vizu.identidade.onboarding.dto;
import jakarta.validation.constraints.*; public record OnboardingRequest(@NotBlank String nomeFantasia,@NotBlank String razaoSocial,@NotBlank String cnpj,@NotBlank String telefone,@Min(5) @Max(25) short diaVencimento,@NotBlank @Pattern(regexp="[a-z0-9-]{3,63}") String subdominio,@NotBlank String lojaNome,@NotBlank String logradouro,@NotBlank String numero,@NotBlank String bairro,@NotBlank String cidade,@NotBlank @Pattern(regexp="[A-Za-z]{2}") String estado,@NotBlank String cep,@Positive int capacidadeSimultanea,@NotBlank String adminNome,@NotBlank @Email String adminEmail,@NotBlank @Size(min=8,max=100) String senha){}
